# ===== File rewrite logic =====

def js_str(s: str) -> str:
    """Encode a Python str as a TS double-quoted string literal."""
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n") + '"'

def js_arr(items):
    return "[" + ", ".join(js_str(it) for it in items) + "]"

text = PATH.read_text(encoding="utf-8")

filled = 0  # count of (poi_id, lang, kind) replacements actually done

# Iterate POIs by id markers. We'll find each POI block, then replace empty fields inside.
# Approach: regex split on `id: "<value>",` lines to identify each POI block extent (until next id or end).
ids = list(D.keys())

for poi_id, content in D.items():
    # Find the POI block: from the line containing `id: "{poi_id}",` up to the next `}, image:` line of THAT POI.
    # Simpler: just operate on the smallest matches inside a window.
    # We'll find the index of `id: "{poi_id}"` first, then the closing `}, image: "/poi-images/{poi_id}.webp"},`.
    id_marker = f'id: "{poi_id}",'
    start = text.find(id_marker)
    if start == -1:
        print(f"WARN: POI not found: {poi_id}")
        continue
    # Find end-of-POI marker. Use the image line bound to this POI id.
    end_marker = f'image: "/poi-images/{poi_id}.webp"'
    end_idx = text.find(end_marker, start)
    if end_idx == -1:
        print(f"WARN: POI end marker not found: {poi_id}")
        continue
    block = text[start:end_idx]
    new_block = block

    # descriptionAdvanced fills
    desc = content.get("desc", {})
    for lang, val in desc.items():
        # match  `<lang>: ""` (allow varying indentation), but only inside descriptionAdvanced section.
        # Replace ALL occurrences inside this block — for bordj-bou-arreridj there are duplicate descriptionAdvanced blocks; both need fill.
        pattern = re.compile(r'(\b' + lang + r':\s*)""')
        # However, descriptions and facts both contain lang fields. To distinguish, restrict by checking previous occurrence of "descriptionAdvanced" or "factsAdvanced".
        # Easier: do two passes — first find descriptionAdvanced sections, then factsAdvanced sections, and within each, replace empty.
        pass  # handled below

    # Helper to replace empties within named subsections.
    def replace_in_section(b: str, section: str, lang: str, replacement: str, is_array: bool):
        """Replace the empty field for (section, lang) within block b. Returns (new_b, count)."""
        count = 0
        # Find all occurrences of f"{section}: {{" in b.
        idx = 0
        while True:
            sec_pos = b.find(f"{section}: {{", idx)
            if sec_pos == -1:
                break
            # Find matching closing brace for this section (naive: nearest '\n    }')
            close_pos = b.find("    }", sec_pos)
            if close_pos == -1:
                break
            sub = b[sec_pos:close_pos]
            # Replace `<lang>: ""` or `<lang>: []` with replacement (only if currently empty).
            if is_array:
                pat = re.compile(r'(\b' + re.escape(lang) + r':\s*)\[\]')
            else:
                pat = re.compile(r'(\b' + re.escape(lang) + r':\s*)""')
            new_sub, n = pat.subn(lambda m: m.group(1) + replacement, sub, count=1)
            if n > 0:
                b = b[:sec_pos] + new_sub + b[close_pos:]
                count += n
                idx = sec_pos + len(new_sub)
            else:
                idx = close_pos + 1
        return b, count

    for lang, val in content.get("desc", {}).items():
        new_block, n = replace_in_section(new_block, "descriptionAdvanced", lang, js_str(val), is_array=False)
        filled += n
    for lang, items in content.get("facts", {}).items():
        new_block, n = replace_in_section(new_block, "factsAdvanced", lang, js_arr(items), is_array=True)
        filled += n

    if new_block != block:
        text = text[:start] + new_block + text[end_idx:]

PATH.write_text(text, encoding="utf-8")
print(f"Total fields filled: {filled}")






